<template><section>
  <div class="controls"><label>Cell type <select v-model="cell" @change="load"><option v-for="item in catalogue" :key="item.cellType">{{item.cellType}}</option></select></label><label>Color by <select v-model="color"><option v-for="f in fields" :key="f">{{f}}</option></select></label><label>Hover label <select v-model="label"><option v-for="f in fields" :key="f">{{f}}</option></select></label><label>X <select v-model.number="pcx"><option v-for="i in 10" :value="i">PC{{i}}</option></select></label><label>Y <select v-model.number="pcy"><option v-for="i in 10" :value="i">PC{{i}}</option></select></label></div>
  <p v-if="error" role="alert">{{error}} <button @click="load">Retry</button></p><p v-else-if="busy" role="status">Loading cell-type PCA…</p>
  <template v-if="data"><p class="source">PanKbase v3.3 · {{data.rows.length}} pseudobulk samples · Existing source PCA coordinates</p><ScatterPlot :rows="points" :x-label="`PC${pcx}`" :y-label="`PC${pcy}`" :title="`${cell}-PCA`"/><div class="legend"><span v-for="item in legend" :key="item.label"><i :style="{background:item.color}"/>{{item.label}}</span></div><button @click="download">Download displayed coordinates</button>
    <div class="controls"><label>Gene contributions <select v-model.number="pc"><option v-for="i in 10" :value="i">PC{{i}}</option></select></label><button @click="downloadContributions">Download contributions</button><button @click="downloadContributionPlot">Download contribution plot</button></div>
    <p>Top ten genes contributing to variability along PC{{pc}}</p><table><thead><tr><th>Gene</th><th>Contribution (%)</th></tr></thead><tbody><tr v-for="[gene,value] in data.contributions[pc-1]" :key="gene"><td>{{gene}}</td><td><span class="bar" :style="{width:`${value/maxContribution*100}px`}"/>{{value.toPrecision(4)}}</td></tr></tbody></table>
    <details><summary>Source &amp; methods</summary><p>These are the upstream log-normalized pseudobulk PCA scores, not donor-level differential expression. All source samples and the ten PCs offered by the original application are retained. Contributions are squared source prcomp loadings normalized over all genes for each PC.</p><a href="https://data.pankbase.org/method/pca_analysismethods" target="_blank" rel="noopener">PCA methods</a><p>Source commit: {{data.source.commit}}</p></details>
  </template>
</section></template>
<script>
import { scaleOrdinal, schemeTableau10, scaleSequential, interpolateViridis, extent } from 'd3';
import { localJson, downloadText } from './assets.mjs';
import ScatterPlot from './ScatterPlot.vue';
export default {
  components:{ScatterPlot},props:['context'],data:()=>({catalogue:[],cell:'Acinar',data:null,error:'',busy:false,pcx:1,pcy:2,pc:1,color:'Program',label:'Description of diabetes status',serial:0}),
  computed:{fields(){return this.data?.fields||[];},numeric(){return this.data?.numericFields.includes(this.color);},scale(){return this.numeric?scaleSequential(interpolateViridis).domain(extent(this.data.rows.map(r=>r.attributes[this.color]).filter(Number.isFinite))):scaleOrdinal(schemeTableau10).domain([...new Set(this.data.rows.map(r=>r.attributes[this.color]))].sort());},points(){if(!this.data)return[];return this.data.rows.map(r=>({x:r.scores[this.pcx-1],y:r.scores[this.pcy-1],color:r.attributes[this.color]===null?'#94a3b8':this.scale(r.attributes[this.color]),label:`${this.label}: ${r.attributes[this.label]??'Unknown'}`}));},legend(){if(!this.data)return[];return (this.numeric?this.scale.domain():this.scale.domain()).map(v=>({label:String(v),color:this.scale(v)}));},maxContribution(){return Math.max(...this.data.contributions[this.pc-1].map(r=>r[1]));}},
  async mounted(){await this.load();},
  methods:{downloadContributionPlot(){
    const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('xmlns',ns);svg.setAttribute('width','720');svg.setAttribute('height','440');svg.setAttribute('viewBox','0 0 720 440');
    const add=(tag,attrs,text)=>{const e=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));if(text!==undefined)e.textContent=text;svg.appendChild(e);};
    add('rect',{width:720,height:440,fill:'white'});add('text',{x:24,y:30,'font-size':18,'font-family':'sans-serif'},`${this.cell} · PC${this.pc} · top gene contributions (%)`);
    this.data.contributions[this.pc-1].forEach(([gene,value],i)=>{const y=62+i*34;add('text',{x:150,y:y+16,'text-anchor':'end','font-family':'sans-serif','font-size':13},gene);add('rect',{x:165,y,width:430*value/this.maxContribution,height:22,fill:'#0f827d'});add('text',{x:605,y:y+16,'font-size':13,'font-family':'sans-serif'},value.toPrecision(5));});
    add('text',{x:24,y:420,'font-size':12,'font-family':'sans-serif'},'PanKbase v3.3 · normalized squared source PCA loadings');downloadText(new XMLSerializer().serializeToString(svg),`${this.cell}-PC${this.pc}-contributions.svg`,'image/svg+xml');
  },async load(){const token=++this.serial;this.error='';this.busy=true;this.data=null;try{if(!this.catalogue.length){this.catalogue=(await localJson('data/manifest.json')).pca;const match=this.catalogue.find(i=>i.cellType.toLowerCase()===this.context.cellType?.toLowerCase());if(match)this.cell=match.cellType;}const item=this.catalogue.find(i=>i.cellType===this.cell);const data=await localJson('data/'+item.asset);if(token===this.serial)this.data=data;}catch(e){if(token===this.serial)this.error=e.message;}finally{if(token===this.serial)this.busy=false;}},download(){downloadText(['PC'+this.pcx+'\tPC'+this.pcy+'\t'+this.color,...this.data.rows.map(r=>[r.scores[this.pcx-1],r.scores[this.pcy-1],r.attributes[this.color]].join('\t'))].join('\n'),`${this.cell}-PCA.tsv`);},downloadContributions(){downloadText(['gene\tcontribution_percent',...this.data.contributions[this.pc-1].map(r=>r.join('\t'))].join('\n'),`${this.cell}-PC${this.pc}-contributions.tsv`);}},
};
</script>
